import { StudySession } from '../models/StudySession';

/** Result of saveFinishedSession(): the values stored in the database. */
export interface SavedSession {
  /** study_sessions.session_id, generated by the database. */
  sessionId: number;
  /**
   * users.points and users.lifetime_points after the session's points were added.
   * If the user bought an item while the session was being finished, these values
   * already include that purchase (PointResult.newBalance was computed before it).
   */
  points: number;
  lifetimePoints: number;
}

/**
 * Data access for finished study sessions (FR-16), Repository Pattern.
 *
 * Used when a session is finished (Use Case 2 and Use Case 4 sequence diagrams):
 *   1. PointService.awardPoints(user, session, pointsEarnedToday) sets session.pointsEarned,
 *   2. saveFinishedSession(session) is the step "save session (pointsEarned)
 *      and updated user balances".
 *
 * Business classes depend only on this interface, so unit tests can pass a fake
 * object instead of a database. PgSessionRepository is the PostgreSQL implementation.
 */
export interface SessionRepository {
  /**
   * Total points the user has earned today (0 if none). It is the
   * pointsEarnedToday input of PointCalculationStrategy.calculatePoints();
   * only DailyCapPointStrategy uses it (risk R4, disabled by default).
   */
  pointsEarnedToday(userId: number): Promise<number>;

  /**
   * Saves the finished session and adds session.pointsEarned to the user's
   * points and lifetime points in ONE database transaction: either both are
   * saved or nothing is. A session that earned 0 points is saved too (FR-8, FR-16).
   * session.sessionId is ignored; the database generates the id.
   * Throws if the user does not exist.
   */
  saveFinishedSession(session: StudySession): Promise<SavedSession>;
}
